def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    def is_valid(cell):
        return 0 <= cell[0] < rows and 0 <= cell[1] < cols and grid[cell[0]][cell[1]] == '.'

    q = [start]
    seen = set([start])
    while q:
        p = q.pop(0)
        if p == goal:
            return [p]
        for d in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            cell = (p[0] + d[0], p[1] + d[1])
            if is_valid(cell) and cell not in seen:
                seen.add(cell)
                q.append(cell)
    return []
